/* File: annot-tsv.c, line ~115 */
void cols_append(cols_t *cols, char *str)
{
    if ( cols->rmme )
    {
        size_t str_len = strlen(str);
        size_t lst_len = strlen(cols->off[ cols->n - 1 ]);
        size_t tot_len = 2 + str_len + lst_len + (cols->off[ cols->n - 1 ] - cols->rmme);

        cols_t *tmp_cols = (cols_t*)calloc(1,sizeof(cols_t));
        if ( !tmp_cols ) error("Out of memory, failed to allocate %zu bytes\n",sizeof(cols_t));
        tmp_cols->rmme = calloc(tot_len,1);
        tmp_cols->off  = calloc(cols->n+1,sizeof(*tmp_cols->off));
        if ( !tmp_cols->rmme || !tmp_cols->off ) error("Out of memory\n");

        char *ptr = tmp_cols->rmme;
        int i;
        for (i=0; i<cols->n; i++)
        {
            size_t len = strlen(cols->off[i]);
            memcpy(ptr, cols->off[i], len);
            tmp_cols->off[i] = ptr;
            ptr += len + 1;
        }
        memcpy(ptr, str, str_len);
        tmp_cols->off[i] = ptr;   /* <‑‑ no NUL written here */

        free(cols->off);
        free(cols->rmme);
        cols->rmme = tmp_cols->rmme;
        cols->off  = tmp_cols->off;
        cols->n    = cols->n+1;
        cols->m    = cols->n;
        free(tmp_cols);
        return;
    }
    /* … the “else” branch that simply stores the pointer … */
}
```

* **What it does** – It appends a new column string to a `cols_t` structure that already owns a contiguous buffer (`rmme`) containing all previous column strings, each NUL‑terminated.  
* **The bug** – After copying the new string into the buffer (`memcpy(ptr, str, str_len);`) the code never writes a terminating `'\0'`.  Consequently, the last string in the buffer is not NUL‑terminated.  Any later call to `strlen()` or a function that expects a NUL‑terminated string will read past the end of the buffer, potentially leaking memory contents or causing a crash.

